B.aqU=new A.au("KULLANIM KO\u015eULLARI, H\u0130ZMET SA\u011eLAYICI SORUMSUZLUK KAYDI VE 6698 SAYILI KVKK KAPSAMINDA \u0130\u015eLETME VER\u0130 SORUMLUSU TAAHH\xdcTNAMES\u0130",null,B.amg,null,null,null,null,null,null)
